"""Reports: docs/fame-report.md and docs/prompt-candidates.md. Both are regenerated by `python3 pipeline/generate.py`."""
from __future__ import annotations

import random
from collections import Counter
from pathlib import Path

import pandas as pd

from fame import MIN_SEASON_GAMES
from generator import GenerationResult, MAX_PLAYER_ANSWERS, MIN_PLAYER_ANSWERS, MIN_TEAM_ANSWERS
from templates import PLAYER, TEAM, TEMPLATES, Template
from tiers import CUTOFFS, DEEP_TIER, LAST_TIER, TIER_LABELS, TIER_POINTS

SAMPLE_SEED = 2026
REVIEW_NOTES = Path(__file__).resolve().parent / "data" / "fame-review.md"

# (name, kind, tier bound, why we expect it). 'max' means the tier should be this or better (lower number).
SANITY = [
    ("LeBron James", "max", 1, "all-time great"), ("Kobe Bryant", "max", 1, "all-time great"),
    ("Tim Duncan", "max", 1, "all-time great"), ("Dirk Nowitzki", "max", 1, "all-time great"),
    ("Stephen Curry", "max", 1, "superstar"), ("Kevin Durant", "max", 1, "superstar"),
    ("Giannis Antetokounmpo", "max", 1, "superstar"), ("Nikola Jokic", "max", 1, "superstar"),
    ("Luka Doncic", "max", 1, "young star"), ("Shai Gilgeous-Alexander", "max", 1, "young star"),
    ("Victor Wembanyama", "max", 2, "young star, few seasons"), ("Anthony Edwards", "max", 2, "young star"),
    ("Cade Cunningham", "max", 2, "young star"), ("Jalen Brunson", "max", 2, "young star"),
    ("Paolo Banchero", "max", 2, "young star"), ("Chet Holmgren", "max", 2, "young star, defensive"),
    ("Cooper Flagg", "max", 2, "rookie star, one season"), ("Tyrese Haliburton", "max", 2, "young star"),
    ("Michael Jordan", "max", 1, "most famous player ever, but only his last two seasons (2001-02 and 2002-03, Wizards) are in the data"),
    ("Ben Wallace", "max", 2, "four-time Defensive Player of the Year, scorer in name only"),
    ("Brian Scalabrine", "min", 4, "famous bench player: a deep-ish name"), ("Jason Kapono", "min", 3, "role player"),
]


def _md_table(headers: list[str], rows: list[list[object]]) -> list[str]:
    out = ["| " + " | ".join(headers) + " |", "|" + "|".join(["---"] * len(headers)) + "|"]
    return out + ["| " + " | ".join(str(c) for c in r) + " |" for r in rows]


def _ppg(row: pd.Series) -> str:
    return "none" if pd.isna(row["best_ppg"]) else f"{row['best_ppg']:.1f} ({int(row['best_ppg_season'])}, {int(row['best_ppg_games'])} g)"


def _nominal_shares() -> dict[int, float]:
    shares, previous = {}, 0
    for percent, tier in CUTOFFS:
        shares[tier] = float(percent - previous)
        previous = percent
    shares[LAST_TIER] = float(100 - previous)
    return shares


def render_fame_report(fame: pd.DataFrame) -> str:
    n = len(fame)
    L = ["# Fame report", "", "Written by `python3 pipeline/generate.py`; do not edit by hand (the review notes at the end come from `pipeline/data/fame-review.md`).", ""]
    L += [
        "## How the fame score works", "",
        f"- **Population:** {n:,} players with at least one game with a points value (2001-02 to the last season in the data).",
        "- **Two metrics:** career points (regular season plus playoffs), and best single-season points per game "
        f"(regular season only, at least {MIN_SEASON_GAMES} games that season, games for all teams added up).",
        "- **Ranks:** each metric is ranked across all players (rank 1 = most famous; ties share the better rank). A player's fame rank is the "
        "better (lower) of the two, so a short-career star is not rated obscure. Players with no 40-game season have no points-per-game rank "
        "and are ranked by career points alone. Both percentiles divide by the same number of players, so they are on the same scale.",
        "- **Tier:** from the global percentile = fame rank / players: top 3% is tier 1 (10 points), 3 to 10% tier 2 (20), 10 to 25% tier 3 (35), "
        "25 to 50% tier 4 (55), 50 to 75% tier 5 (75), the rest tier 6 (100). A player exactly on a cutoff gets the better-known tier.",
        "- **Only games in the data count**, so a player whose career started before 2001-02 is judged on his later years only.",
        "",
    ]

    counts = fame["tier"].value_counts().to_dict()
    nominal = _nominal_shares()
    L += ["## Players per tier", ""]
    L += _md_table(
        ["tier", "points", "percentile band", "nominal share", "nominal players", "actual players", "actual share"],
        [[t, TIER_POINTS[t], TIER_LABELS[t], f"{nominal[t]:.0f}%", f"{nominal[t] * n / 100:.0f}", counts.get(t, 0), f"{counts.get(t, 0) * 100 / n:.1f}%"] for t in range(1, 7)],
    )
    top = counts.get(1, 0) + counts.get(2, 0)
    L += [
        "",
        f"The better-known tiers are fuller than the nominal shares ({counts.get(1, 0)} players in tier 1 against {0.03 * n:.0f}). That follows from the method: "
        f"taking the better of two ranks lets a player in through either door, so up to twice as many players can sit in the top 3% (tier 1 and 2 together: {top}).",
        "",
    ]

    L += ["## The 40 most famous players", ""]
    rows = []
    for i, r in fame.head(40).iterrows():
        rows.append([i + 1, r["name"], f"{int(r['career_points']):,}", _ppg(r), f"{r['fame_pct']:.2f}%", r["tier"], r["fame_source"]])
    L += _md_table(["#", "player", "career points", "best points per game", "fame percentile", "tier", "decided by"], rows) + [""]

    L += [f"## 15 random players per tier (seed {SAMPLE_SEED})", ""]
    for t in range(1, 7):
        pool = fame[fame["tier"] == t]
        pick = pool.sample(n=min(15, len(pool)), random_state=SAMPLE_SEED).sort_values("fame_rank")
        L += [f"### Tier {t} ({TIER_POINTS[t]} points, {TIER_LABELS[t]}): {len(pool)} players", ""]
        L += _md_table(
            ["player", "career points", "best points per game", "fame percentile"],
            [[r["name"], f"{int(r['career_points']):,}", _ppg(r), f"{r['fame_pct']:.2f}%"] for _, r in pick.iterrows()],
        ) + [""]

    L += ["## Sanity check on recognizable names", ""]
    rows, flagged = [], []
    by_name = fame.set_index("name")
    for name, kind, bound, why in SANITY:
        if name not in by_name.index:
            rows.append([name, why, "-", "-", "-", "-", "not in the data"])
            continue
        r = by_name.loc[name]
        ok = r["tier"] <= bound if kind == "max" else r["tier"] >= bound
        want = f"tier {bound} or better" if kind == "max" else f"tier {bound} or worse"
        rows.append([name, f"{why}; expect {want}", r["tier"], f"{r['fame_pct']:.2f}%", f"{int(r['career_points']):,}", _ppg(r), "ok" if ok else "**CHECK**"])
        if not ok:
            flagged.append(f"{name} (tier {int(r['tier'])})")
    L += _md_table(["player", "why and what we expect", "tier", "fame percentile", "career points", "best points per game", "verdict"], rows) + [""]
    L += [("Names that did not come out as expected: " + ", ".join(flagged) + ".") if flagged else "Every name came out as expected.", ""]

    if REVIEW_NOTES.exists():
        L += ["## Review notes", "", REVIEW_NOTES.read_text().strip(), ""]
    return "\n".join(L).rstrip() + "\n"


def _examples(items: list[tuple[dict, dict]], k: int = 3) -> list[tuple[dict, dict]]:
    """k candidates spread from the shortest valid-answer list to the longest."""
    if len(items) <= k:
        return items
    ordered = sorted(items, key=lambda pm: len(pm[0]["answers"]))
    picks = sorted({round(i * (len(ordered) - 1) / (k - 1)) for i in range(k)})
    return [ordered[i] for i in picks]


def render_candidates_report(result: GenerationResult, templates: list[Template] | None = None) -> str:
    templates = templates if templates is not None else TEMPLATES
    attempts = pd.DataFrame(result.attempts)
    L = ["# Prompt candidates", "", "Written by `python3 pipeline/generate.py`; do not edit by hand.", ""]
    L += [
        f"- **Era wording:** every prompt starts with \"{result.era}\". The data's season 2002 is the 2001-02 season (the first game is on 2001-10-30), "
        "so \"Since 2002\" would leave out three months of games. The schema requires the text to start with \"Since\" and four digits, which this does.",
        f"- **Valid answers:** players need {MIN_PLAYER_ANSWERS} to {MAX_PLAYER_ANSWERS}; teams need at least {MIN_TEAM_ANSWERS}.",
        f"- **Player tiers** come from the fame score (docs/fame-report.md). **Team tiers:** a team is tier 1 (10 points) if it qualified under its current name "
        "in any qualifying season, tier 4 (55 points) if only under a historical name. Every team answer is the franchise, shown by its current name; the other names it used are aliases for the answer matcher.",
        "- **Difficulty:** from the number of valid answers and the share of tier 4 and above (see `difficulty()` in `pipeline/generator.py`).",
        "",
    ]
    kept = attempts[attempts["status"] == "kept"]
    L += [
        "## Totals", "",
        f"- Candidates: **{len(result.prompts)}** ({sum(1 for p in result.prompts if p['answerType'] == PLAYER)} player, {sum(1 for p in result.prompts if p['answerType'] == TEAM)} team).",
        f"- Tried: {len(attempts)} template and threshold combinations. Dropped for too few valid answers: {int((attempts['status'] == 'too_few').sum())}. "
        f"Dropped for too many: {int((attempts['status'] == 'too_many').sum())}.",
        "- By difficulty: " + ", ".join(f"{d} {c}" for d, c in sorted(Counter(p["difficulty"] for p in result.prompts).items())) + ".",
        "",
    ]
    none = [t.key for t in templates if kept[kept["template"] == t.key].empty]
    L += ["Templates that produced no candidates: " + (", ".join(f"`{k}`" for k in none) if none else "none") + ".", ""]

    L += ["## Candidates per template", ""]
    rows = []
    for t in templates:
        a = attempts[attempts["template"] == t.key]
        ok = a[a["status"] == "kept"]
        few = a[a["status"] == "too_few"]
        many = a[a["status"] == "too_many"]
        rows.append([f"`{t.key}`", t.answer_type, ", ".join(str(x) for x in a["n"]) if "{n}" in t.wording else "-", len(ok), len(few), len(many)])
    L += _md_table(["template", "answers", "thresholds tried", "candidates", "dropped: too few", "dropped: too many"], rows) + [""]

    L += ["## What was dropped", ""]
    for t in templates:
        a = attempts[(attempts["template"] == t.key) & (attempts["status"] != "kept")]
        if len(a):
            parts = [f"{'n=' + str(r.n) if '{n}' in t.wording else 'no threshold'}: {r.valid_answers} answers ({r.status.replace('_', ' ')})" for r in a.itertuples()]
            L.append(f"- `{t.key}`: " + "; ".join(parts))
    L.append("")

    pm_by_template: dict[str, list[tuple[dict, dict]]] = {}
    for p, m in zip(result.prompts, result.meta):
        pm_by_template.setdefault(m["template"], []).append((p, m))
    for answer_type, title in ((PLAYER, "Player templates: examples"), (TEAM, "Team templates: examples")):
        L += [f"## {title}", "", "Three candidates per template, from the shortest list to the longest. Each answer is shown as name (tier).", ""]
        for t in [t for t in templates if t.answer_type == answer_type]:
            items = pm_by_template.get(t.key, [])
            L += [f"### `{t.key}`", ""]
            if not items:
                L += ["No candidates: every threshold gave too few or too many valid answers (see above).", ""]
                continue
            for p, m in _examples(items):
                tiers = [a["tier"] for a in p["answers"]]
                L += [
                    f"**{p['text']}**", "",
                    f"{len(p['answers'])} valid answers, difficulty **{p['difficulty']}**, tiers: " + ", ".join(f"{k}: {v}" for k, v in m["tier_counts"].items() if v) + f" ({sum(1 for x in tiers if x >= DEEP_TIER)} at tier {DEEP_TIER} or above).", "",
                ]
                if answer_type == TEAM and m.get("historical_only"):
                    L += ["Qualified only under a historical name: " + ", ".join(m["historical_only"]) + ".", ""]
                L += ["<details><summary>All valid answers</summary>", "", ", ".join(f"{a['name']} ({a['tier']})" for a in p["answers"]), "", "</details>", ""]
    return "\n".join(L).rstrip() + "\n"


def write_reports(fame: pd.DataFrame, result: GenerationResult, docs_dir: Path) -> None:
    docs_dir.mkdir(parents=True, exist_ok=True)
    (docs_dir / "fame-report.md").write_text(render_fame_report(fame))
    (docs_dir / "prompt-candidates.md").write_text(render_candidates_report(result))
